package in.malabartrails;
import io.jsonwebtoken.Jwts;import io.jsonwebtoken.security.Keys;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.authentication.BadCredentialsException;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import javax.crypto.SecretKey;import java.io.IOException;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.*;
@Component
public class AuthService extends OncePerRequestFilter {
 private final SecretKey key;private final StaffRepository users;private final org.springframework.security.crypto.password.PasswordEncoder encoder;
 public AuthService(@Value("${app.jwt-secret}")String secret,StaffRepository users,org.springframework.security.crypto.password.PasswordEncoder encoder){this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.users=users;this.encoder=encoder;}
 public void login(String email,String password,HttpServletResponse response){StaffUser u=users.findByEmailIgnoreCase(email).orElseThrow(()->new BadCredentialsException("Invalid credentials"));if(!encoder.matches(password,u.passwordHash))throw new BadCredentialsException("Invalid credentials");String jwt=Jwts.builder().subject(u.email).claim("role",u.role).issuedAt(new Date()).expiration(Date.from(Instant.now().plusSeconds(3600))).signWith(key).compact();Cookie legacy=new Cookie("mt_session","");legacy.setHttpOnly(true);legacy.setPath("/api");legacy.setMaxAge(0);legacy.setAttribute("SameSite","Lax");response.addCookie(legacy);Cookie cookie=new Cookie("mt_session",jwt);cookie.setHttpOnly(true);cookie.setSecure(false);cookie.setPath("/");cookie.setMaxAge(3600);cookie.setAttribute("SameSite","Lax");response.addCookie(cookie);}
 @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws IOException,ServletException{String token=Arrays.stream(Optional.ofNullable(req.getCookies()).orElse(new Cookie[0])).filter(c->c.getName().equals("mt_session")).map(Cookie::getValue).findFirst().orElse(null);if(token!=null){try{var claims=Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();var auth=new UsernamePasswordAuthenticationToken(claims.getSubject(),null,List.of(()->"ROLE_"+claims.get("role",String.class)));SecurityContextHolder.getContext().setAuthentication(auth);}catch(Exception ignored){}}chain.doFilter(req,res);}
}
